      await Hive.box(ReaderPrefs.boxName).flush();
      await Hive.box(ReaderPrefs.boxName).close();
      await ReaderPrefs.init();
      expect(ReaderPrefs().textAlignJustify, value, reason: 'Survives reopening storage');
    }
  });
  test('ReaderPrefs.novelPaginated: on, off, and restart', () async {
    final prefs = ReaderPrefs();
    for (final value in [true, false]) {
      await prefs.setNovelPaginated(value);
      expect(prefs.novelPaginated, value);
      await Hive.box(ReaderPrefs.boxName).flush();
      await Hive.box(ReaderPrefs.boxName).close();
      await ReaderPrefs.init();
      expect(ReaderPrefs().novelPaginated, value, reason: 'Survives reopening storage');
    }
  });
}
